// Story theater copy (five locales), keyed for storyVnCampaign.js,
// storyVnPartTwo.js and storyVnPartThree.js. PRODUCT_AUTHORED.
// Pure data + resolver; registered as a scoped dictionary in
// scripts/check-locale-coverage.mjs. Placeholders: {tamer}, {partner}, {n}, {total}, {have}, {need}, {name}.

export const STORY_VN_LOCALES = Object.freeze(["zh-Hant", "en", "ja", "th", "vi"]);

const freezeDeep = value => {
  if (Array.isArray(value)) { for (const item of value) freezeDeep(item); return Object.freeze(value); }
  if (value && typeof value === "object") { for (const item of Object.values(value)) freezeDeep(item); return Object.freeze(value); }
  return value;
};

