    "TASK_BREAK": "點擊故障回送裝置（{n}/{total}）",
    "TASK_CHEER": "點擊看台，把歡呼送回場上（{n}/{total}）",
    "TASK_COLLECT": "點擊回聲收集器，放走被關住的歡呼（{n}/{total}）",
    "TASK_COSIGN": "依序按下兩個陣營的金鑰",
    "TASK_IDENTIFY": "點擊居民，找回名字（{n}/{total}）",
    "V1_NAVI_INVITE": "{tamer}，地方錦標賽的報名窗口今天傍晚就截止囉！傳送門已經替你們調好座標，快出發吧！",
    "V1_N_AVATAR": "在 Data Area 裡，馴獸師的聲音會借由拍檔的身影傳遞——你聽見的是人的話語，映入眼簾的則是寸步不離守在身旁的拍檔。",
    "V1_N_HEAVY": "咚、咚、咚——沉重得不像尋常腳步的震動順著石板傳來。原本吵嚷的人群像是撞見什麼，自動往兩側讓出了一條路。",
    "V1_P_SEARCH": "等等我！再一下下、剛剛明明就滾到這片葉子底下的——找到了！",
    "V2_NAVI_TRUCE": "心輝議會跟黑鐵駭客竟然同時發來聯名調查邀請……{tamer}，這在錦標賽史上可是頭一遭喔。",
    "V3_NAVI_DIVE": "訊號深度已達第七層。{tamer}，這裡干擾太強，千萬別讓 {partner} 走出你的視線！",
    "V4_NAVI_SEAL": "兩道鎖的加密波段完全互斥——看來非得心輝跟黑鐵同時轉下金鑰，這扇門才肯開口。",
    "V5_NAVI_ALERT": "糟糕！全區廣播頻道遭強行接管！{tamer}，所有終端機的名字欄……正在同時清空成空白！",
    "V6_LOSE": "撐住別倒！防線還沒破——趁現在，跟我一起把這鬼東西頂回去！",
    "V6_NAVI_ALL": "三條戰線全數打通！{tamer}，這一刻，所有人都在同一個頻道替你們撐腰！",
    "V6_RESONANCE": "刺目而溫暖的光芒自 {partner} 胸口湧出——那是你們從牧場清晨一路並肩走到此刻，點滴攢下的共鳴。",
    "VN_AUTO": "自動",
    "VN_BACK": "回到星圖",
    "VN_BATTLE_GO": "開始對戰",
    "VN_BATTLE_LOST": "這一場輸了",
    "VN_BATTLE_REFUSED": "現在無法開始對戰，劇情直接往下走。",
    "VN_BATTLE_FAILED": "戰鬥沒開成",
    "VN_BATTLE_RETRY": "重試",
    "VN_BATTLE_BACK": "返回",
    "VN_BATTLE_WON": "勝利！",
    "VN_BOND_LINE": "與{partner}的羈絆 ♥ +1",
    "VN_BOND_TOTAL": "累計羈絆 ♥ {n}",
    "VN_CHAPTER_NUM": "第 {n} 章",
