    "V3_NAVI_DIVE": "第七層まで潜行。{tamer}、ここは信号が乱れてる。{partner} を見える場所に置いておいてね。",
    "V4_NAVI_SEAL": "二つの錠前は波形がまるで違う。両方が一緒に鍵を回さないと開かないみたい。",
    "V5_NAVI_ALERT": "全域チャンネルが乗っ取られた！ {tamer}、すべての端末の名前欄が……一斉に空白になっていく！",
    "V6_LOSE": "踏ん張れ！今のを止められなくても、ルートはまだある——一緒に押し返すぞ！",
    "V6_NAVI_ALL": "三つのルートが同時に開いた。{tamer}、今度はみんな同じチャンネルにいる。",
